DROP TABLE IF EXISTS `bodegaapp_movimientostock`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `bodegaapp_movimientostock` (
  `id` bigint NOT NULL AUTO_INCREMENT,
  `tipo` varchar(15) NOT NULL,
  `cantidad` int NOT NULL,
  `saldo` int unsigned NOT NULL,
  `fecha` datetime(6) NOT NULL,
  `motivo` varchar(200) NOT NULL,
  `bodega_id` bigint NOT NULL,
  `item_id` bigint NOT NULL,
  `prestamo_id` bigint DEFAULT NULL,
  `solicitud_id` bigint DEFAULT NULL,
  `unidad_id` bigint DEFAULT NULL,
  `usuario_id` bigint DEFAULT NULL,
  `espacio_id` bigint DEFAULT NULL,
  `revierte_id` bigint DEFAULT NULL,
  PRIMARY KEY (`id`),
  UNIQUE KEY `revierte_id` (`revierte_id`),
  KEY `bodegaApp_movimiento_bodega_id_0cc32562_fk_bodegaApp` (`bodega_id`),
  KEY `bodegaApp_movimientostock_item_id_cc83c0fb_fk_bodegaApp_item_id` (`item_id`),
  KEY `bodegaApp_movimiento_prestamo_id_1c8934f6_fk_bodegaApp` (`prestamo_id`),
  KEY `bodegaApp_movimiento_solicitud_id_84a731a3_fk_bodegaApp` (`solicitud_id`),
  KEY `bodegaApp_movimiento_unidad_id_8495d4af_fk_bodegaApp` (`unidad_id`),
  KEY `bodegaApp_movimiento_usuario_id_fbb8d84e_fk_bodegaApp` (`usuario_id`),
  KEY `bodegaApp_movimientostock_tipo_1fd4712d` (`tipo`),
  KEY `bodegaApp_movimientostock_fecha_c21a64aa` (`fecha`),
  KEY `bodegaApp_movimiento_espacio_id_38db3d73_fk_bodegaApp` (`espacio_id`),
  CONSTRAINT `bodegaApp_movimiento_bodega_id_0cc32562_fk_bodegaApp` FOREIGN KEY (`bodega_id`) REFERENCES `bodegaapp_bodega` (`id`),
  CONSTRAINT `bodegaApp_movimiento_espacio_id_38db3d73_fk_bodegaApp` FOREIGN KEY (`espacio_id`) REFERENCES `bodegaapp_espacio` (`id`),
  CONSTRAINT `bodegaApp_movimiento_prestamo_id_1c8934f6_fk_bodegaApp` FOREIGN KEY (`prestamo_id`) REFERENCES `bodegaapp_prestamo` (`id`),
  CONSTRAINT `bodegaApp_movimiento_revierte_id_03aa04a6_fk_bodegaApp` FOREIGN KEY (`revierte_id`) REFERENCES `bodegaapp_movimientostock` (`id`),
  CONSTRAINT `bodegaApp_movimiento_solicitud_id_84a731a3_fk_bodegaApp` FOREIGN KEY (`solicitud_id`) REFERENCES `bodegaapp_solicitud` (`id`),
  CONSTRAINT `bodegaApp_movimiento_unidad_id_8495d4af_fk_bodegaApp` FOREIGN KEY (`unidad_id`) REFERENCES `bodegaapp_unidad` (`id`),
  CONSTRAINT `bodegaApp_movimiento_usuario_id_fbb8d84e_fk_bodegaApp` FOREIGN KEY (`usuario_id`) REFERENCES `bodegaapp_usuario` (`id`),
  CONSTRAINT `bodegaApp_movimientostock_item_id_cc83c0fb_fk_bodegaApp_item_id` FOREIGN KEY (`item_id`) REFERENCES `bodegaapp_item` (`id`),
  CONSTRAINT `bodegaapp_movimientostock_chk_1` CHECK ((`saldo` >= 0))
) ENGINE=InnoDB AUTO_INCREMENT=882 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci;
